        if not math.isfinite(kl):
            raise ValueError("KL must be finite")
        kls.append(kl)
        if kl > t:
            stopped = True
            break

    return {
        "logits": L,
        "objectives": objectives,
        "probabilities": probabilities,
        "kls": kls,
        "stopped": stopped,
    }


